const icon=(n='file')=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.file}</svg>`;
const brand=`<a class="brand" href="/" aria-label="T&T Contabilidade — início"><img class="brand-emblem" src="/assets/marca-tt-original.png" width="56" height="56" alt="" decoding="async"><span class="brand-word">T&T<small>CONTABILIDADE</small></span></a>`;
const button=(text,href='/abrir-empresa',cls='')=>`<a class="button ${cls}" href="${href}">${text}</a>`;
const link=(text,href)=>`<a class="text-link" href="${href}">${text} ${icon('arrow')}</a>`;
const services=[['Abrir empresa grátis','abrir-empresa','building','Abra seu CNPJ sem burocracia.','Abertura de empresa'],['Contabilidade completa','contabilidade-online','chart','Obrigações fiscais acompanhadas por especialistas.','Contabilidade mensal'],['Emissor de nota fiscal','emissor-nota-fiscal','file','Emita e organize suas notas pela plataforma.','Notas fiscais'],['Impostos','impostos','calc','Visualize guias, valores e vencimentos.','Impostos'],['Folha de pagamento','folha-pagamento','people','Gerencie funcionários, salários e encargos.','Folha de pagamento'],['Assessoria contábil','assessoria-contabil','chat','Converse com especialistas quando precisar.','Atendimento contábil']];
const moreServices=[['Trocar de contador','trocar-contador','Mude de contador com uma transição organizada.'],['Deixar de ser MEI','deixar-mei','Planeje o próximo passo da sua empresa.'],['Regularizar CNPJ','regularizar-cnpj','Entenda as pendências e organize sua regularização.'],['Alteração contratual','alteracao-contratual','Atualize as informações da sua empresa.'],['Baixa de empresa','baixa-empresa','Encerre seu CNPJ com orientação em cada etapa.'],['Escritório virtual','escritorio-virtual','Conheça as opções de endereço comercial e fiscal.'],['Certificado digital','certificado-digital','Identificação digital para a rotina da sua empresa.'],['Conta PJ','conta-pj','Separe as finanças pessoais das empresariais.'],['Cobrança de clientes','cobranca-clientes','Organize recebimentos e acompanhe suas cobranças.'],['Gestão financeira','gestao-financeira','Tenha clareza sobre entradas, saídas e resultados.'],['Pró-labore','pro-labore','Organize a remuneração dos sócios.'],['Plano de saúde','plano-saude','Conheça possibilidades de cuidado para sua equipe.'],['Benefícios empresariais','beneficios-empresariais','Avalie benefícios de acordo com a realidade da empresa.'],['Academias','academias','Conheça possibilidades de bem-estar para sua equipe.'],['Psicologia e nutrição','psicologia-nutricao','Avalie opções de cuidado e qualidade de vida.'],['Seguros','seguros','Conheça alternativas de proteção para seu negócio.']];
