const faqs=[['Quanto custa uma contabilidade online?','O valor depende da atividade, do faturamento, do número de sócios e da equipe. Compare os planos e solicite uma proposta com todos os serviços e condições discriminados.'],['Como abrir um CNPJ?','Comece informando sua atividade e cidade. Depois, a equipe avalia a viabilidade, orienta a documentação e acompanha os registros necessários. Taxas de órgãos públicos e serviços adicionais dependem do seu caso.'],['Quanto tempo demora para abrir uma empresa?','O prazo depende da cidade, da atividade, da documentação e das análises dos órgãos responsáveis. Uma previsão deve ser confirmada após a avaliação do seu caso.'],['Posso trocar de contador?','Sim. A transição envolve organizar os documentos, definir a data de início e alinhar a entrega das informações com a contabilidade anterior.'],['Vocês atendem MEI?','A proposta inclui orientação sobre a rotina do MEI e a transição para microempresa. Consulte o atendimento para confirmar o escopo adequado à sua atividade.'],['Como funciona a emissão de nota fiscal?','A emissão depende do cadastro da empresa e das autorizações do município ou estado. A equipe orienta a configuração. A área do cliente deste site apresenta uma demonstração visual do emissor.'],['Quais impostos uma empresa paga?','Isso depende da atividade, do regime tributário, do faturamento e da localização. As calculadoras apresentam estimativas; a apuração definitiva precisa considerar a situação fiscal da empresa.'],['Vocês atendem minha cidade?','O atendimento foi pensado para ser online. A disponibilidade dos serviços e dos registros locais deve ser confirmada na análise de viabilidade para sua cidade.'],['Como envio meus documentos?','Em uma operação integrada, os documentos são enviados pela área segura do cliente. Nesta demonstração, nenhum documento ou dado de contato é transmitido.'],['Consigo falar com um contador?','Acesse a página de contato e escolha o assunto do atendimento. O canal comercial oficial ainda precisa ser cadastrado para ativar o envio.']];
const megaCol=(title,items)=>`<div><h3>${title}</h3>${items.map(([t,h])=>`<a href="${h}">${t}</a>`).join('')}</div>`;
const serviceMenu=megaCol('SERVIÇOS DE CONTABILIDADE',[['Abrir empresa grátis','/abrir-empresa'],['Contabilidade completa','/contabilidade-online'],...moreServices.slice(0,5).map(s=>[s[0],'/'+s[1]]),['Assessoria contábil','/assessoria-contabil']])+megaCol('GESTÃO DA EMPRESA',[['Escritório virtual','/escritorio-virtual'],['Emissor de nota fiscal','/emissor-nota-fiscal'],['Certificado digital','/certificado-digital'],['Conta PJ','/conta-pj'],['Cobrança de clientes','/cobranca-clientes'],['Gestão financeira','/gestao-financeira'],['Folha de pagamento','/folha-pagamento'],['Pró-labore','/pro-labore']])+megaCol('PARA VOCÊ',moreServices.slice(11).map(s=>[s[0],'/'+s[1]]).concat([['Certificado digital','/certificado-digital']]));
