let header=`<a class="skip" href="#principal">Pular para o conteúdo</a><header class="site-header"><div class="header-inner">${brand}<nav class="nav" id="navigation" aria-label="Navegação principal"><details class="menu"><summary>Serviços</summary><div class="mega"><div class="mega-grid">${serviceMenu}</div><div class="mega-bottom"><strong>Não sabe qual serviço escolher?</strong>${button('Falar com um contador','/contato','small')}</div></div></details><a href="/planos">Planos</a><a href="/para-empresas">Para empresas</a><a href="/calculadoras">Calculadoras</a><details class="menu"><summary>Conteúdos</summary><div class="mega"><div class="mega-grid">${contentMenu}</div></div></details><a href="/como-funciona">Como funciona</a><a href="/ajuda">Dúvidas</a></nav><div class="header-actions"><a href="/login">Entrar</a><a class="header-contact" href="/contato">Falar com contador</a>${button('<span class="desktop-label">Abrir minha empresa</span><span class="mobile-label">Abrir empresa</span>','/abrir-empresa','small')}<button class="mobile-toggle" aria-label="Abrir menu" aria-controls="navigation" aria-expanded="false"><svg class="icon" viewBox="0 0 24 24"><path d="M3 6h18M3 12h18M3 18h18"/></svg></button></div></div></header>`;
