const footerGroups=[['SERVIÇOS',[['Abrir empresa','/abrir-empresa'],['Trocar contador','/trocar-contador'],['Contabilidade completa','/contabilidade-online'],['Deixar de ser MEI','/deixar-mei'],['Regularização','/regularizar-cnpj'],['Assessoria contábil','/assessoria-contabil']]],['PARA SUA EMPRESA',[['Emissor de notas','/emissor-nota-fiscal'],['Escritório virtual','/escritorio-virtual'],['Certificado digital','/certificado-digital'],['Conta PJ','/conta-pj'],['Folha de pagamento','/folha-pagamento'],['Cobranças','/cobranca-clientes']]],['CALCULADORAS',calcs.filter((_,i)=>i!==3&&i!==7).map(c=>[c[0],'/calculadoras/'+c[1]])],['CONTEÚDOS',[['Blog','/blog'],['Guias','/guias'],['E-books','/guias#ebooks'],['Cursos','/guias#curso'],['Tabela Simples Nacional','/blog/tabela-simples-nacional']]],['EMPRESA',[['Sobre nós','/sobre'],['Como funciona','/como-funciona'],['Parceiros','/parceiros'],['Carreiras','/carreiras'],['Contato','/contato']]],['SUPORTE',[['Central de ajuda','/ajuda'],['Fale conosco','/contato'],['WhatsApp','/contato#canais'],['Status da plataforma','/status']]],['LEGAL',[['Termos de uso','/termos'],['Política de privacidade','/privacidade'],['LGPD','/lgpd'],['Política de cookies','/cookies']]],['ACOMPANHE',[['Instagram','/redes-sociais'],['LinkedIn','/redes-sociais'],['YouTube','/redes-sociais']]]];
const footer=`<footer class="footer"><div class="container"><div class="footer-top"><div>${brand}<p>Contabilidade próxima de você.<br>Tecnologia a favor da sua empresa.</p></div><div>${link('Vamos conversar','/contato')}<p>Atendimento online.<br>Mais clareza para o seu negócio.</p></div></div><div class="footer-columns">${footerGroups.map(([t,items])=>`<div class="footer-column"><h3>${t}</h3>${items.map(([n,h])=>`<a href="${h}">${n}</a>`).join('')}${t==='LEGAL'?'<button data-cookies>Preferências de cookies</button>':''}</div>`).join('')}</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} T&T Contabilidade. Todos os direitos reservados.</span><span>T&T Contabilidade · Dados institucionais e CRC a cadastrar.</span><span class="developer-credit">Desenvolvido por <strong>Arthur R</strong></span></div></div></footer>`;
const cookies=`<aside class="cookie-banner" aria-label="Preferências de privacidade" hidden><p><strong>Sua privacidade importa.</strong> Usamos armazenamento local para lembrar suas preferências. Você decide sobre recursos não essenciais. <a href="/cookies"><u>Saiba mais</u></a></p><div class="actions"><button class="plain-button" data-cookies>Configurar</button><button class="button secondary" data-consent="reject">Recusar não essenciais</button><button class="button" data-consent="accept">Aceitar</button></div></aside><dialog id="cookie-dialog" aria-labelledby="cookie-title"><button class="dialog-close" data-close aria-label="Fechar">×</button><h2 id="cookie-title">Sua privacidade, suas escolhas.</h2><p>Nesta versão, não há ferramentas de publicidade ou análise de visitas. Suas escolhas ficam salvas somente neste navegador.</p><div class="cookie-option"><div><strong>Essenciais</strong><p>Preferências de privacidade.</p></div><span>Sempre ativos</span></div><label class="cookie-option"><span><strong>Análise de uso</strong><br>Permissão para recursos futuros.</span><input type="checkbox" id="analytics-pref"></label><label class="cookie-option"><span><strong>Marketing</strong><br>Permissão para recursos futuros.</span><input type="checkbox" id="marketing-pref"></label><div class="form-actions"><button class="button secondary" data-consent="reject">Recusar opcionais</button><button class="button" id="save-cookies">Salvar escolhas</button></div></dialog><dialog id="info-dialog" aria-labelledby="info-title"><button class="dialog-close" data-close aria-label="Fechar">×</button><h2 id="info-title">Demonstração</h2><div id="info-content"></div></dialog>`;
const cta=()=>`<section class="section"><div class="container"><div class="final-cta"><div class="cta-copy"><div class="cta-brand"><img src="/assets/marca-tt-original.png" width="64" height="64" alt="" loading="lazy"><span>T&T <small>CONTABILIDADE</small></span></div><h2>Pronto para simplificar sua contabilidade?</h2><p>Cuide do seu negócio. Deixe a burocracia com quem entende.</p></div><div class="actions">${button('Abrir minha empresa '+icon('arrow'))}${button('Falar com especialista','/contato','outline-light')}</div></div></div></section>`;
const sectionHead=(eyebrow,title,desc='',center=false)=>`<div class="section-head ${center?'center':''}"><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>`;
