const steps=()=>`<div class="steps">${[['Conte sobre sua empresa.','Sua atividade, sua cidade e o momento do seu negócio.'],['Nós cuidamos da documentação.','Orientação para reunir os documentos e dar o próximo passo.'],['Seu CNPJ e sua contabilidade ficam organizados.','Uma rotina clara, do cadastro às obrigações.'],['Você acompanha tudo pela plataforma.','Informações acessíveis para decidir com tranquilidade.']].map(([t,d],i)=>`<article class="step"><span class="step-number">0${i+1}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>`;
const planNames=['Essencial','Profissional','Premium'];
