const plans=()=>`<div class="billing" role="group" aria-label="Período de contratação"><button data-billing="Mensal" aria-pressed="true">Mensal</button><button data-billing="Anual" aria-pressed="false">Anual</button></div><div class="grid3">${planNames.map((t,i)=>`<article class="plan ${i===1?'featured':''}">${i===1?'<span class="popular">MAIS ESCOLHIDO · ILUSTRATIVO</span>':''}<h3>${t.toUpperCase()}</h3><p>${['Para quem está começando.','Para empresas em crescimento.','Para acompanhamento completo.'][i]}</p><div class="price">Consulte <small class="billing-caption">/ mês</small></div><div class="plan-note">Proposta conforme o perfil da empresa.</div>${button('Conhecer o plano','/contato?plano='+t,i===1?'':'secondary')}<ul class="benefits">${planBenefits[i].map(b=>`<li>${b}</li>`).join('')}</ul></article>`).join('')}</div><p class="muted-note" style="text-align:center;margin-top:24px">Estrutura de planos demonstrativa. Valores, limites, condições e disponibilidade serão definidos na proposta. A abertura gratuita depende de contratação e confirmação comercial; taxas públicas não estão incluídas.</p><details class="comparison"><summary>Compare todos os recursos dos planos</summary><div class="table-scroll" tabindex="0" role="region" aria-label="Comparação dos planos"><table><thead><tr><th>O que está incluído</th>${planNames.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${['Contabilidade mensal','Obrigações fiscais','Emissão de notas','Atendimento','Folha de pagamento','Pró-labore','Certificado digital','Conta PJ','Relatórios financeiros','Atendimento prioritário'].map((t,i)=>`<tr><th scope="row">${t}</th>${[0,1,2].map(p=>`<td>${i<2?'Previsto na proposta':i===3?['Digital','Digital + acompanhamento','Consultivo'][p]:i===8?['Sob consulta','Gerenciais','Gerenciais + análise'][p]:'Sob consulta'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`;
const faq=()=>`<div class="faq">${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
