const home=()=>`<section class="hero"><div class="container hero-grid"><div class="hero-copy"><div class="eyebrow">T&T Contabilidade · Digital completa</div><h1>Contabilidade simples.<br>Sua empresa pronta para <em>crescer.</em></h1><p>Abra seu CNPJ, emita notas fiscais, organize impostos e tenha contadores especialistas cuidando da sua empresa em um só lugar.</p><div class="actions">${button('Abrir empresa grátis '+icon('arrow'))}${button('Falar com um contador','/contato','secondary')}</div><div class="check-grid"><span>Processo 100% online</span><span>Suporte especializado</span><span>Plataforma disponível 24h</span><span>Segurança dos seus dados</span></div><p class="muted-note" style="font-size:.68rem;margin-top:16px;margin-bottom:0">Abertura sujeita às condições do plano. Taxas públicas à parte.</p></div><div class="hero-visual"><div class="hero-brand-seal" aria-label="T&T Contabilidade"><img src="/assets/marca-tt-original.png" width="80" height="80" alt="" decoding="async"></div><img class="hero-photo" src="${heroImg}" width="540" height="475" alt="Profissional trabalhando com notebook em um escritório contemporâneo" fetchpriority="high"><div class="float-card top"><span class="status-icon">${icon('check')}</span><div><strong>Impostos em dia</strong><small>Mais tranquilidade para você.</small></div></div><div class="float-card right"><span class="status-icon">${icon('file')}</span><div><strong>Nota fiscal emitida</strong><small>Tudo certo. Tudo organizado.</small></div></div><div class="float-card bottom"><span class="status-icon">${icon('clock')}</span><div><small>Próximo vencimento</small><strong>10 OUT <span style="font-size:.67rem;font-weight:400;color:#526071">· Guia de impostos</span></strong></div></div><span class="photo-caption"><strong>Seu negócio em primeiro lugar.</strong>Rotina da plataforma ilustrativa.</span></div></div></section><section class="trust-strip"><div class="container"><div class="trust-grid"><div class="trust-intro">Menos burocracia.<br>Mais espaço para o seu negócio.</div><div><strong>100% online</strong><small>Do primeiro contato à rotina</small></div><div><strong>De perto</strong><small>Atendimento especializado</small></div><div><strong>Em um só lugar</strong><small>Gestão contábil organizada</small></div></div></div></section><section class="section"><div class="container"><div class="section-row">${sectionHead('Uma parceria completa','Tudo da sua empresa<br>em um só lugar.','Centralize a rotina contábil e ganhe tempo para fazer o que você faz de melhor.')}${link('Conheça nossos serviços','/servicos')}</div>${serviceGrid()}</div></section><section class="section platform"><div class="container"><div class="section-row">${sectionHead('Tecnologia que aproxima','Sua contabilidade<br>na palma da mão.','Menos planilhas espalhadas. Mais clareza sobre os números, os prazos e o próximo passo da sua empresa.')}<div class="actions">${button('Conhecer a plataforma '+icon('arrow'),'/area-cliente','outline-light')}</div></div>${dashboard()}<p class="demo">Interface demonstrativa. Dados e valores ilustrativos.</p></div></section><section class="section"><div class="container">${sectionHead('Simples desde o início','Contabilidade sem complicação.','Você conta com orientação em cada etapa. Nós organizamos o caminho.',true)}${steps()}</div></section><section class="section pale" id="planos"><div class="container">${sectionHead('Encontre o seu plano','Um plano para cada momento<br>da sua empresa.','Clareza sobre o que você contrata. Atendimento de acordo com o que precisa.',true)}${plans()}</div></section><section class="section"><div class="container"><div class="section-row">${sectionHead('Decisões com clareza','Faça as contas antes de decidir.','Ferramentas simples para comparar possibilidades e planejar os próximos passos.')}${link('Ver todas as calculadoras','/calculadoras')}</div>${calculatorGrid()}</div></section><section class="section pale"><div class="container">${sectionHead('Seu trabalho, nossa especialidade','Para quem faz acontecer.','Cada atividade tem sua rotina. Sua contabilidade também precisa acompanhar.')}<div class="professions">${professions.map((p,i)=>`<a class="profession" href="/para-empresas/${slug(p)}">${icon(['code','briefcase','chart','heart','people','building'][i%6])}${p}</a>`).join('')}</div></div></section><section class="section"><div class="container">${sectionHead('Quem empreende, entende','Empreendedores que simplificaram a contabilidade.','Exemplos de como os depoimentos aparecerão. Substitua por relatos reais autorizados.')}<div class="grid3">${[['Marina A.','Design e comunicação','Ter os documentos organizados em um lugar facilita muito a rotina de quem trabalha por conta própria.'],['Lucas C.','Desenvolvimento de software','Eu queria entender meus números e saber o que vence no mês. É essa clareza que faz a diferença.'],['Renata S.','Consultoria de negócios','Poder tirar dúvidas com alguém que entende do meu negócio é o tipo de apoio que eu valorizo.']].map(([n,p,t],i)=>`<article class="quote-card"><div class="stars" aria-label="Avaliação ilustrativa de cinco estrelas">★★★★★</div><blockquote>“${t}”</blockquote><div class="quote-person">${i===0?`<img src="${personImg}" loading="lazy" width="45" height="45" alt="Imagem ilustrativa de profissional; não representa cliente real">`:`<span class="avatar">${n.charAt(0)}</span>`}<div><strong>${n}</strong><small>${p}</small></div></div><small>Depoimento demonstrativo · pessoa fictícia</small></article>`).join('')}</div></div></section><section class="section pale"><div class="container security-grid"><div>${sectionHead('Confiança em cada detalhe','Os dados da sua empresa protegidos.','Cuidado com as informações faz parte de uma boa contabilidade. Conheça os critérios previstos para a plataforma.')}<p class="muted-note">Recursos de segurança operacional e políticas da empresa devem ser validados antes da ativação dos serviços. Não há certificações declaradas.</p>${link('Conheça nossa política de privacidade','/privacidade')}</div><div class="security-items">${[['lock','Conexão criptografada'],['file','Proteção de documentos'],['shield','Controle de acesso'],['cloud','Backups'],['lock','Privacidade'],['shield','Adequação à LGPD']].map(([i,t])=>`<div class="security-item">${icon(i)}<strong>${t}</strong></div>`).join('')}</div></div></section><section class="section"><div class="container faq-layout"><div>${sectionHead('Pode perguntar','Suas dúvidas,<br>sem complicação.','Se precisar, converse com a gente. Você não precisa entender tudo de contabilidade para cuidar bem da sua empresa.')}${button('Falar com um contador','/contato','secondary')}</div>${faq()}</div></section>${cta()}`;
const pageHero=(title,desc,category='T&T Contabilidade')=>`<section class="page-hero"><div class="container"><nav class="breadcrumb" aria-label="Localização"><a href="/">Início</a><span aria-hidden="true">/</span><span>${title}</span></nav><div class="eyebrow">${category}</div><h1>${title}</h1><p>${desc}</p></div></section>`;
const pages=new Map();
const add=(route,title,description,body)=>pages.set(route,{title,description,body});
add('/','Contabilidade online para sua empresa','Abra sua empresa, organize impostos, notas fiscais e folha de pagamento com a T&T Contabilidade.',home());
add('/servicos','Serviços de contabilidade','Abertura, contabilidade mensal, notas fiscais e atendimento para sua empresa.',pageHero('Mais organização. Em cada etapa.','Da abertura do CNPJ à rotina do mês, encontre o apoio que faz sentido para sua empresa.','Nossos serviços')+`<section class="section"><div class="container">${serviceGrid()}<h2 style="margin-top:64px">Apoio para outros momentos.</h2><div class="grid3">${moreServices.map(([t,h,d])=>`<article class="service-card"><div class="icon-box">${icon('briefcase')}</div><h3>${t}</h3><p>${d}</p>${link('Conhecer serviço','/'+h)}</article>`).join('')}</div></div></section>`+cta());
for(const [t,h,d] of services.filter(s=>s[1]!=='abrir-empresa').map(s=>[s[0],s[1],s[3]]).concat(moreServices)){
 const specific={ 'trocar-contador':['Organizar a transição','Reúna o contrato atual, a situação das obrigações e o histórico contábil. Alinhamos a data da troca e a passagem das informações.'], 'deixar-mei':['Preparar o próximo passo','O desenquadramento pode alterar obrigações e custos. Informe sua atividade e o motivo da mudança para uma avaliação individual.'], 'regularizar-cnpj':['Começar pelo diagnóstico','Identifique a situação cadastral e as pendências nos órgãos responsáveis. O plano de regularização depende da análise de cada obrigação.'], 'emissor-nota-fiscal':['Notas fiscais, sem perder o controle','Organize tomadores, descrições e documentos emitidos. A emissão real depende de integração e autorização fiscal; a plataforma apresentada é demonstrativa.'], 'folha-pagamento':['Uma rotina clara para sua equipe','Organize admissões, informações mensais, recibos e obrigações. O escopo e o custo acompanham a quantidade de funcionários e a operação.'], 'certificado-digital':['Identidade digital da sua empresa','O tipo de certificado depende do uso. Emissão, validação e renovação precisam de proposta e atendimento por prestador habilitado.']}[h]||['Entenda o que sua empresa precisa','Começamos conhecendo a atividade, a cidade e a operação. A proposta informa o escopo, os valores, as responsabilidades e a disponibilidade do serviço.'];
 add('/'+h,t,d,pageHero(t,d,'Serviços')+`<section class="section"><div class="container inner-grid"><div class="content-body"><h2>${specific[0]}</h2><p>${specific[1]}</p><h3>O caminho é simples</h3><ul><li>Conte como funciona sua empresa.</li><li>Receba a análise de necessidades e uma proposta.</li><li>Confira documentos, prazos e condições.</li><li>Acompanhe o próximo passo com orientação.</li></ul><div class="callout">Disponibilidade, prazos e valores sujeitos à avaliação. Nenhuma contratação é concluída automaticamente.</div></div><aside class="form-card"><div class="icon-box">${icon('chat')}</div><h2>Vamos entender seu momento?</h2><p>Informe o serviço que procura e prepare sua solicitação.</p>${button('Conversar sobre '+t.toLowerCase(),'/contato?assunto='+encodeURIComponent(t))}${link('Comparar planos','/planos')}</aside></div></section>`+cta());
}
add('/planos','Planos de contabilidade','Compare os serviços e encontre uma proposta para sua empresa.',pageHero('Um plano para cada momento da sua empresa.','Escolha o acompanhamento que combina com sua rotina. Consulte valores e condições antes de contratar.','Planos transparentes')+`<section class="section pale"><div class="container">${plans()}</div></section>`+cta());
add('/como-funciona','Como funciona','Conheça as etapas da contabilidade digital T&T.',pageHero('Contabilidade sem complicação.','Da primeira conversa ao acompanhamento mensal: um caminho claro para você.','Como funciona')+`<section class="section"><div class="container">${steps()}<div style="margin-top:50px">${dashboard()}</div><p class="muted-note">Demonstração da plataforma com dados fictícios.</p></div></section>`+cta());
add('/para-empresas','Contabilidade para sua atividade','Atendimento pensado para diferentes profissionais e empresas.',pageHero('Sua atividade tem suas particularidades.','Conheça a organização contábil para o seu jeito de empreender.','Para empresas')+`<section class="section"><div class="container"><div class="grid3">${professions.map((p,i)=>`<article class="service-card"><div class="icon-box">${icon(dashIcons[i])}</div><h3>${p}</h3><p>Organize a rotina e conheça as necessidades da sua atividade.</p>${link('Saiba mais','/para-empresas/'+slug(p))}</article>`).join('')}</div></div></section>`);
for(const p of professions)add('/para-empresas/'+slug(p),'Contabilidade para '+p.toLowerCase(),'Orientação para organizar a rotina contábil da sua atividade.',pageHero('Contabilidade para '+p.toLowerCase()+'.','Sua atividade no centro do atendimento. Da organização dos documentos ao acompanhamento das obrigações.','Para sua empresa')+`<section class="section"><div class="container inner-grid"><div class="content-body"><h2>Mais tempo para o seu trabalho.</h2><p>A organização começa pela escolha das atividades da empresa, análise do modelo de contratação e entendimento da sua operação.</p><ul><li>Abertura ou regularização do CNPJ.</li><li>Organização de notas, receitas e despesas.</li><li>Acompanhamento das obrigações aplicáveis.</li><li>Orientação para pró-labore e folha, quando necessários.</li></ul></div><div class="form-card"><h2>Atendimento para ${p.toLowerCase()}</h2><p>Converse sobre seu negócio e confirme o escopo de atendimento.</p>${button('Falar com especialista','/contato?assunto='+encodeURIComponent(p))}</div></div></section>`+cta());
const field=(id,label,type='text',extra='')=>`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" ${extra}><small class="error" id="${id}-error"></small></div>`;
const wizard=()=>`<form id="opening-form" novalidate><div class="form-step-count" aria-live="polite">Etapa <span id="step-current">1</span> de 5</div><div class="progress-line"><span id="step-progress" style="width:20%"></span></div><section class="form-step" data-step="0"><h2>Qual atividade você exerce?</h2><p>Conte com suas palavras. Vamos entender o que você faz.</p>${field('activity','Sua atividade','text','required placeholder="Ex.: desenvolvimento de software" autocomplete="organization-title"')}</section><section class="form-step" data-step="1" hidden><h2>Onde sua empresa ficará?</h2><p>A cidade ajuda a orientar a análise de viabilidade.</p>${field('city','Cidade','text','required placeholder="Ex.: Belo Horizonte" autocomplete="address-level2"')}<div class="field"><label for="state">Estado</label><select id="state" name="state" required><option value="">Selecione</option>${'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ').map(v=>`<option>${v}</option>`).join('')}</select></div></section><section class="form-step" data-step="2" hidden><h2>Quanto pretende faturar por mês?</h2><p>Uma estimativa já ajuda. Você pode ajustar depois.</p>${field('revenue','Faturamento mensal estimado (R$)','number','min="0" step="0.01" required placeholder="15000"')}</section><section class="form-step" data-step="3" hidden><h2>Sua empresa terá funcionários?</h2><p>Assim podemos considerar a rotina de folha.</p><div class="field"><label for="employees">Previsão de funcionários</label><select id="employees" name="employees" required><option value="">Selecione</option><option>Sem funcionários por enquanto</option><option>1 a 5 funcionários</option><option>6 ou mais funcionários</option><option>Ainda não sei</option></select></div></section><section class="form-step" data-step="4" hidden><h2>Como podemos falar com você?</h2>${field('name','Seu nome','text','required minlength="2" autocomplete="name"')}${field('email','E-mail','email','required autocomplete="email"')}${field('phone','Telefone com DDD','tel','required minlength="10" autocomplete="tel"')}<label style="display:flex;gap:10px;align-items:start;font-size:.8rem"><input id="contact-consent" type="checkbox" required>Li a <a href="/privacidade"><u>política de privacidade</u></a> e entendi que este é um formulário demonstrativo.</label><div class="demo">Seu resumo será preparado neste navegador. Nenhum dado será enviado à T&T nesta versão.</div></section><p id="wizard-error" class="error" role="alert"></p><div class="form-actions"><button type="button" class="button secondary" id="step-back" hidden>Voltar</button><button type="submit" class="button" id="step-next">Continuar ${icon('arrow')}</button></div></form><div id="wizard-success" hidden></div>`;
add('/abrir-empresa','Abra sua empresa online','Prepare sua abertura de CNPJ em cinco etapas simples.',pageHero('Seu próximo capítulo começa aqui.','Conte sobre o seu negócio. Vamos organizar as informações para a abertura da sua empresa.','Abertura de empresa')+`<section class="section pale"><div class="container inner-grid"><div><div class="eyebrow">Do plano ao CNPJ</div><h2>Abra sua empresa<br>com o caminho claro.</h2><p>Um passo de cada vez, sem pedir tudo de uma só vez.</p><ul class="benefits"><li>Orientação sobre atividade e documentação</li><li>Análise da viabilidade na sua cidade</li><li>Contabilidade desde o primeiro passo</li><li>Proposta com condições claras</li></ul><div class="callout"><strong>Abertura grátis?</strong><p style="margin:10px 0 0;font-size:.9rem">Oferta sujeita à contratação de plano e validação comercial. Taxas de registro, licenças e custos de terceiros são avaliados à parte.</p></div></div><div class="form-card">${wizard()}</div></div></section>`);
const source='https://www8.receita.fazenda.gov.br/SimplesNacional/Arquivos/manual/PerguntaoSN.pdf';
const num=(id,label,value,extra='')=>field(id,label,'number',`value="${value}" min="0" step="0.01" required ${extra}`);
const calcFields={
 'fator-r':num('payroll','Folha e encargos considerados nos últimos 12 meses (R$)',84000)+num('rbt','Receita bruta dos últimos 12 meses (R$)',300000,'min="0.01"'),
 'pj-clt':num('clt','Salário CLT líquido mensal (R$)',6000)+num('benefits','Benefícios mensais CLT (R$)',800)+num('pj','Receita mensal como PJ (R$)',10000)+num('rate','Alíquota estimada PJ (%)',10,'max="100"')+num('cost','Custos mensais PJ (R$)',600)+num('months','Meses faturados por ano',11,'max="12" step="1"'),
 'simples-nacional':num('rbt','Receita bruta dos últimos 12 meses (R$)',300000,'min="0.01"')+num('monthly','Receita do mês (R$)',25000)+num('nominal','Alíquota nominal da sua faixa (%)',11.2,'max="100"')+num('deduction','Parcela a deduzir da sua faixa (R$)',9360)+'<p class="muted-note">Exemplo editável de faixa do Anexo III. Confirme os parâmetros na tabela oficial correspondente à sua atividade.</p>',
 'custo-abrir-empresa':num('registry','Taxas de registro (R$)',0)+num('license','Licenças e alvarás (R$)',0)+num('certificate','Certificado digital (R$)',0)+num('service','Honorários de abertura (R$)',0)+num('other','Outros custos (R$)',0),
 'impostos':num('monthly','Receita mensal tributável (R$)',20000)+num('rate','Alíquota efetiva estimada (%)',6,'max="100"'),
 'pro-labore':num('gross','Pró-labore bruto (R$)',4000)+num('social','Contribuição previdenciária informada (R$)',440)+num('income','Imposto de renda informado (R$)',0)+num('other','Outros descontos (R$)',0),
 'rpa':num('gross','Valor bruto do serviço (R$)',3000)+num('social','INSS retido informado (R$)',0)+num('income','IRRF informado (R$)',0)+num('other','ISS e outras retenções (R$)',0),
 'salario':num('gross','Salário bruto (R$)',5000)+num('social','INSS informado (R$)',0)+num('income','IRRF informado (R$)',0)+num('other','Outros descontos (R$)',0)
};
add('/calculadoras','Calculadoras para sua empresa','Compare cenários, estime custos e organize decisões.',pageHero('Faça as contas antes de decidir.','Simulações transparentes, com parâmetros que você pode ajustar.','Calculadoras')+`<section class="section"><div class="container">${calculatorGrid(true)}<div class="callout">As ferramentas oferecem estimativas para planejamento. Confira as premissas de cada simulação antes de utilizar os resultados.</div></div></section>`);
for(const [t,h,d] of calcs)add('/calculadoras/'+h,'Calculadora de '+t,d,pageHero('Calculadora de '+t,d,'Planeje com clareza')+`<section class="section"><div class="container inner-grid"><form class="form-card" id="calculator-form" data-calculator="${h}">${calcFields[h]}<p class="error" id="calculator-error" role="alert"></p><button class="button" type="submit">Calcular resultado ${icon('arrow')}</button></form><aside class="result" aria-live="polite"><h2>Sua simulação</h2><div id="calculation-result"><p>Confira os valores e clique em calcular para ver o resultado.</p></div><hr style="border:0;border-top:1px solid #345071;margin:24px 0"><p class="muted-note">${h==='pj-clt'?'Comparação simplificada anual: considera 13 salários líquidos, adicional de férias estimado em 1/3 do líquido, 12 meses de benefícios e os meses de faturamento PJ informados. Não inclui FGTS, verbas rescisórias ou benefícios não informados.':h==='fator-r'?'Para atividades sujeitas ao Fator R, a relação entre folha elegível e receita dos últimos 12 meses orienta o enquadramento. A composição da folha e as regras de empresas novas exigem análise específica.':h==='simples-nacional'?'Fórmula: (receita em 12 meses × alíquota nominal − parcela a deduzir) ÷ receita em 12 meses. Não considera segregações, retenções, sublimites ou regras de início de atividade.':'Estimativa aritmética baseada exclusivamente nos valores informados. Não calcula automaticamente tabelas de retenção, tetos, deduções ou regras fiscais.'}</p>${['fator-r','simples-nacional'].includes(h)?`<a style="font-size:.8rem;text-decoration:underline" href="${source}" target="_blank" rel="noopener">Consultar Receita Federal ↗</a>`:''}<p class="muted-note">Confirme a apuração com um contador.</p></aside></div></section>`);
const articles=blogTopics.map((t,i)=>({title:['O que organizar antes de abrir seu CNPJ','Simples Nacional: o que observar na sua rotina','Do MEI à microempresa: prepare a transição','Como organizar os documentos da contabilidade','Impostos: crie uma rotina de acompanhamento','Notas fiscais: o que conferir antes de emitir','Separe as finanças da empresa e da vida pessoal','CLT ou PJ? Compare mais do que o valor mensal','Como consultar a tabela do Simples Nacional','Guia para começar a trabalhar como PJ'][i],slug:slug(t),topic:t,desc:['Uma lista prática para chegar preparado à primeira conversa.','Atividade, faturamento e organização para conversar com seu contador.','Informações que ajudam a planejar uma nova fase.','Uma organização simples evita dúvidas no fechamento.','Saiba quais informações manter à mão.','Um checklist para reduzir retrabalho no dia a dia.','Tenha mais clareza sobre entradas, saídas e retiradas.','Considere benefícios, reservas e custos na decisão.','Entenda os campos usados na simulação da alíquota.','Documentos e perguntas para organizar seu começo.'][i]}));
const articleCards=()=>`<div class="grid3" id="article-list">${articles.map((a,i)=>`<article class="article-card" data-search="${esc(a.title+' '+a.topic)}"><a href="/blog/${a.slug}"><div class="article-art">${icon(['building','calc','briefcase','file','chart'][i%5])}<span>${a.topic}</span></div><div class="article-copy"><small>${a.topic} · Leitura de 3 min</small><h3>${a.title}</h3><p>${a.desc}</p><span class="text-link">Ler artigo ${icon('arrow')}</span></div></a></article>`).join('')}</div><p id="search-empty" hidden>Nenhum conteúdo encontrado. Tente outro termo.</p>`;
