add('/area-cliente','Demonstração da área do cliente','Explore um conceito visual de gestão contábil com dados fictícios.',`<section class="client-section"><div class="container"><div class="demo">Área demonstrativa · Lucas Studio é uma empresa fictícia. Ações não emitem documentos fiscais nem transmitem dados.</div>${dashboard(false)}<template id="dashboard-home">${dashMain()}<div class="client-actions"><button class="button" data-client-action="Emitir nota">+ Emitir nota</button><button class="button secondary" data-client-action="Enviar documento">Enviar documento</button><button class="button secondary" data-tab="Atendimento">Falar com contador</button><button class="button secondary" data-tab="Impostos">Ver impostos</button></div><div class="dash-columns"><div class="dash-panel"><h4>Últimas notas emitidas</h4>${[['NFS-e 027','Studio Horizonte','R$ 4.500'],['NFS-e 026','Projeto Aurora','R$ 6.200']].map(([n,c,v])=>`<div class="obligation"><div><strong>${n}</strong>${c}</div><span>${v}</span></div>`).join('')}</div><div class="dash-panel"><h4>Mensagens do contador</h4><p><strong>Ana · Equipe contábil</strong></p><p>Lucas, os documentos deste mês estão organizados. Você pode conferir as próximas obrigações no painel.</p><span class="pill">Mensagem ilustrativa</span></div></div></template></div></section>`);
const legalBodies={termos:['Termos de uso','Este site apresenta uma demonstração da experiência digital da T&T Contabilidade. Serviços, preços e condições dependem de proposta validada.','Os formulários preparam resumos localmente. Eles não efetuam contratações, aberturas de empresas, cadastros de clientes ou transmissões de documentos.','As calculadoras são ferramentas de planejamento. Os parâmetros e premissas devem ser conferidos antes de qualquer decisão.','Razão social, CNPJ, endereço, CRC e canal responsável precisam ser cadastrados antes do uso comercial definitivo.'],privacidade:['Política de privacidade','Nesta demonstração, os campos de formulário são processados no navegador. Não existe envio ao atendimento ou armazenamento em banco de dados da T&T.','As preferências de cookies ficam no armazenamento local do navegador. Imagens e fontes externas podem gerar requisições a Pexels e Google Fonts; esses provedores podem receber dados técnicos como endereço IP.','A infraestrutura de hospedagem pode processar registros técnicos de acesso e autenticação conforme suas próprias políticas. O acesso privado da hospedagem é independente da demonstração da área do cliente.','Não há publicidade, análise de visitas ou compartilhamento comercial implementados no código do site.','Os dados do controlador, o canal de privacidade, as bases legais e os prazos de retenção da operação comercial precisam ser definidos antes da ativação de coleta real.'],lgpd:['Privacidade e LGPD','O projeto prevê minimização de dados, clareza de finalidade e controle sobre preferências. Não é declarada certificação ou conformidade jurídica validada.','Na operação real, o titular deve contar com canal para exercer os direitos aplicáveis, incluindo acesso, correção e eliminação quando cabível. Esse canal ainda será cadastrado.','Os formulários desta versão não transmitem dados. Evite preencher documentos sensíveis ou informações que não sejam necessárias.'],cookies:['Política de cookies','O site usa armazenamento local para lembrar as preferências de privacidade. Essa informação pode ser removida nas configurações do navegador.','Não há cookies de publicidade ou ferramentas de análise instaladas no código desta demonstração. Preferências opcionais ficam registradas para o conceito da central, sem ativar rastreadores.','Serviços externos de imagens, fontes e hospedagem podem processar dados técnicos de acesso.','Você pode abrir a central de preferências a qualquer momento pelo rodapé.']};
for(const [route,[title,...paras]] of Object.entries(legalBodies))add('/'+route,title,title+' da T&T Contabilidade.',pageHero(title,'Informações sobre o funcionamento desta versão do site.','Transparência')+`<section class="section"><div class="container legal">${paras.map((p,i)=>`<h2 style="font-size:1.25rem">${i+1}. ${['Sobre esta versão','Funcionamento','Informações importantes','Disponibilidade','Próximos passos'][i]}</h2><p>${p}</p>`).join('')}<button class="button secondary" data-cookies>Gerenciar preferências</button></div></section>`);
