const productionPrivacy=[['Como o site usa suas informações','Seu nome, e-mail, empresa e cidade formam o cadastro. Solicitações, mensagens, movimentações, equipe e documentos são armazenados para os recursos que você utiliza na área do cliente. Não forneça informações além das necessárias.'],['Acesso e armazenamento','A autenticação é realizada pela conta ChatGPT na hospedagem Sites. O servidor verifica a identidade a cada acesso e limita os registros e arquivos à conta responsável. Dados estruturados e arquivos são mantidos separadamente.'],['Preferências e serviços externos','As preferências de privacidade ficam neste navegador. Imagens e fontes externas podem receber dados técnicos como IP. A infraestrutura de hospedagem também processa informações técnicas de acesso conforme suas políticas. Não há publicidade ou análise de visitas instalada.'],['Integrações e comunicação','Nenhuma senha do ChatGPT é recebida pela T&T. Emissão fiscal, pagamento, eSocial, e-mail e WhatsApp não estão integrados. Rascunhos e controles não equivalem a documentos fiscais.'],['Responsável e exercício de direitos','Os dados institucionais do controlador, o canal oficial de privacidade e os prazos de retenção deverão ser validados pela T&T antes do uso comercial. É possível excluir os registros cadastrados na área do cliente. Para a exclusão integral, utilize a opção de exclusão dos dados em Configurações.']];
add('/privacidade','Política de privacidade','Saiba quais dados são processados e como acessar seus controles.',pageHero('Política de privacidade','Informações sobre os dados utilizados nos recursos deste site.','Transparência')+`<section class="section"><div class="container legal">${productionPrivacy.map(([t,p])=>`<h2 style="font-size:1.3rem">${t}</h2><p>${p}</p>`).join('')}<button class="button secondary" data-cookies>Gerenciar preferências</button></div></section>`);
add('/termos','Termos de uso','Entenda o alcance dos recursos da plataforma.',pageHero('Termos de uso','Condições de utilização desta versão da plataforma.','Transparência')+`<section class="section"><div class="container legal"><h2>Uso da plataforma</h2><p>O site permite cadastrar informações, registrar solicitações, guardar documentos e organizar dados da empresa. Contratação de serviços depende de proposta específica validada pela T&T.</p><h2>Limites dos recursos</h2><p>Rascunhos de notas não são documentos fiscais. Os controles não apuram tributos, não transmitem eSocial e não executam pagamentos. A folha apresentada soma os salários informados; não substitui folha oficial.</p><h2>Responsabilidade sobre os dados</h2><p>Informe dados corretos e envie somente documentos que você tenha autorização para armazenar. Não utilize a plataforma para conteúdo ilegal ou para dados de terceiros sem base adequada.</p><h2>Condições comerciais</h2><p>Preços, gratuidade, limites de atendimento e prazos dependem de confirmação comercial. Os dados institucionais e o registro CRC precisam ser cadastrados antes da operação comercial definitiva.</p></div></section>`);
add('/lgpd','Privacidade e LGPD','Controles e informações sobre privacidade.',pageHero('Privacidade e LGPD','Clareza sobre o tratamento das informações.','Transparência')+`<section class="section"><div class="container legal"><h2>Dados limitados à sua conta</h2><p>O acesso aos registros e arquivos é verificado no servidor. Os formulários explicam a finalidade do envio e pedem apenas os dados necessários ao fluxo.</p><h2>Seus controles</h2><p>Você pode atualizar seu cadastro, excluir registros e solicitar a exclusão integral dos dados da conta nas configurações. A autenticação na hospedagem é independente dos dados da plataforma.</p><h2>Validação da operação</h2><p>O canal oficial do controlador, os prazos de retenção e os procedimentos internos precisam de validação institucional. Não é declarada certificação ou conformidade jurídica auditada.</p>${link('Consultar política de privacidade','/privacidade')}</div></section>`);
const favicon='/assets/marca-tt-original.png';
for(const [route,page] of pages){const dest=route==='/'?path.join(dist,'index.html'):route==='/404'?path.join(dist,'404.html'):path.join(dist,route.slice(1),'index.html');fs.mkdirSync(path.dirname(dest),{recursive:true});const schema={ '@context':'https://schema.org','@type':route.startsWith('/blog/')?'Article':'WebPage',name:page.title,description:page.description,url:origin+(route==='/'?'':route),inLanguage:'pt-BR'};fs.writeFileSync(dest,`<!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(page.title)} | T&T Contabilidade</title><meta name="description" content="${esc(page.description)}"><link rel="canonical" href="${origin}${route==='/'?'':route}"><meta property="og:type" content="${route.startsWith('/blog/')?'article':'website'}"><meta property="og:title" content="${esc(page.title)} | T&T Contabilidade"><meta property="og:description" content="${esc(page.description)}"><meta property="og:url" content="${origin}${route==='/'?'':route}"><meta property="og:locale" content="pt_BR"><meta property="og:site_name" content="T&T Contabilidade"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="${esc(page.title)} | T&T Contabilidade"><meta name="twitter:description" content="${esc(page.description)}"><meta name="theme-color" content="#071b3d"><link rel="icon" type="image/png" href="${favicon}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="/styles.css"><style>.mobile-label{display:none}@media(max-width:760px){.mobile-label{display:inline}}</style><script type="application/ld+json">${JSON.stringify(schema)}</script>${route!=='/'?`<script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Início',item:origin},{'@type':'ListItem',position:2,name:page.title,item:origin+route}]})}</script>`:''}<script src="/app.js" defer></script></head><body>${header}<main id="principal">${page.body}</main>${footer}${cookies}</body></html>`);}
fs.mkdirSync(path.join(dist,'materiais'),{recursive:true});
fs.writeFileSync(path.join(dist,'materiais/controle-financeiro.csv'),'\uFEFFData;Descrição;Categoria;Tipo (receita/despesa);Valor;Situação\r\n;;;;;\r\n');
fs.writeFileSync(path.join(dist,'materiais/checklist.txt'),'T&T CONTABILIDADE — CHECKLIST INICIAL\n\n[ ] Notas de receitas e despesas\n[ ] Extratos e comprovantes\n[ ] Informações sobre pessoal\n[ ] Contratos novos ou alterados\n[ ] Dúvidas para a equipe contábil\n\nLista introdutória. Confirme os documentos aplicáveis à sua empresa.\n');
fs.writeFileSync(path.join(dist,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+[...pages.keys()].filter(r=>!['/404','/area-cliente','/login','/cadastro','/administracao'].includes(r)).map(r=>`<url><loc>${origin}${r==='/'?'':r}</loc></url>`).join('')+'</urlset>');
fs.writeFileSync(path.join(dist,'robots.txt'),`User-agent: *\nAllow: /\nDisallow: /area-cliente\nDisallow: /administracao\nSitemap: ${origin}/sitemap.xml\n`);
console.log(`Generated ${pages.size} pages.`);
